package com.bank.promo;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class VoucherBundleGenerator {

    private static final Logger log = Logger.getLogger(VoucherBundleGenerator.class.getName());

    public List<List<Integer>> subsetsWithDup(int[] vouchers) {
        Arrays.sort(vouchers);                         // duplicates become adjacent
        List<List<Integer>> result = new ArrayList<>();
        backtrack(vouchers, 0, new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " unique bundles");
        return result;
    }

    private void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> result) {
        result.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            if (i > start && nums[i] == nums[i - 1]) continue; // skip same-level duplicate
            path.add(nums[i]);
            backtrack(nums, i + 1, path, result);
            path.remove(path.size() - 1);
        }
    }
}
