package com.bank.promo;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SubsetsIIDemo {

    private static final Logger log = Logger.getLogger(SubsetsIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Voucher Bundle Generator (Subsets II)");
        int[] vouchers = {2, 1, 2}; // duplicate voucher value 2
        VoucherBundleGenerator gen = new VoucherBundleGenerator();
        gen.subsetsWithDup(vouchers).forEach(b -> log.info("Bundle: " + b));
    }
}
